/**
 * Word splitting on runs of punctuation and whitespace.
 */

import { isSeparator } from './ascii_classes.mjs';

/**
 * Split `text` on runs of punctuation and ASCII whitespace, discarding empty
 * pieces.
 *
 * Where `String.prototype.split(/\s+/)` would only break on whitespace, this
 * also breaks on punctuation, and it collapses consecutive separators into a
 * single break:
 *
 *     splitPunctWs('Hello, World!')  // -> ['Hello', 'World']
 *     splitPunctWs('a_-_b')          // -> ['a', 'b']
 *     splitPunctWs('!!!')            // -> []
 *
 * Only ASCII separators count. Non-ASCII whitespace (NBSP, U+3000) and
 * non-ASCII punctuation (em dash, guillemets) are ordinary word characters.
 */
export function splitPunctWs(text) {
  const words = [];
  let start = -1;

  for (let i = 0; i < text.length; i++) {
    if (isSeparator(text[i])) {
      if (start !== -1) {
        words.push(text.slice(start, i));
        start = -1;
      }
    } else if (start === -1) {
      start = i;
    }
  }
  if (start !== -1) {
    words.push(text.slice(start));
  }
  return words;
}

