/**
 * String utilities: slug generation.
 */

import { splitPunctWs } from './text_split.mjs';

/**
 * Normalise `text` into a delimiter-separated slug.
 *
 *     slugify('Kurt Gödel\'s pretty cool.')  // -> 'kurt_gödel_s_pretty_cool'
 *     slugify('Hello World', '-')            // -> 'hello-world'
 *     slugify('MIXED Case', '_', false)      // -> 'MIXED_Case'
 *
 * Words are found with {@link splitPunctWs} and rejoined with `delim`, so runs
 * of punctuation and whitespace collapse to a single delimiter and leading or
 * trailing separators fall away entirely.
 *
 * Two behaviours are worth calling out because they are easy to get wrong:
 *
 *  - Input that is non-empty but consists purely of separators has no words to
 *    join, and yields a bare `delim` rather than an empty string. An input that
 *    is itself empty stays empty — there is nothing to stand in for.
 *  - Lowercasing is applied to the *joined* result, not to each word, which is
 *    observable for Greek capital sigma: in `'ΟΔΟΣ ΣΟΦΙΑΣ'` the sigma that ends
 *    the first word is followed by the delimiter, and the Unicode Final_Sigma
 *    rule maps it to `ς` rather than `σ`.
 *
 * Note: the reference also offers an `ascii=True` transliterating mode. It is
 * not reachable from this program (and its Python signature demands a bytes
 * delimiter, which has no counterpart here), so it is deliberately not
 * reimplemented.
 */
export function slugify(text, delim = '_', lower = true) {
  const words = splitPunctWs(text);

  let ret = words.join(delim);
  if (ret === '' && text !== '') {
    ret = delim;
  }

  // JS `toLowerCase` and Python `str.lower()` both apply the Unicode full
  // lowercase mappings, including the contextual Final_Sigma rule and the
  // İ (U+0130) -> 'i' + U+0307 expansion, so no fixups are needed here.
  return lower ? ret.toLowerCase() : ret;
}

