/**
 * Error types raised while parsing, and the exit codes that go with them.
 */

/** A problem with one specific argument; rendered as `argument <name>: <msg>`. */
export class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(argumentName === null ? message : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
  }
}

/** A usage error: print usage plus the message to stderr and exit 2. */
export class UsageError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UsageError';
    this.status = 2;
  }
}

/** Raised when an action wants the program to stop, e.g. `--help`. */
export class ParserExit extends Error {
  constructor(status, output) {
    super(`parser exited with status ${status}`);
    this.name = 'ParserExit';
    this.status = status;
    this.output = output;
  }
}

