/**
 * Usage and help text rendering.
 *
 * Layout constants and the help-column formula are chosen to reproduce the
 * reference formatter byte for byte for the option set this program declares.
 */

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `A` in `--a A`: what the option's value is called in help output. */
function argsString(action) {
  return action.metavar ?? action.dest.toUpperCase();
}

/** `[-h]` / `--a A`: how an option appears in the one-line usage summary. */
function formatUsagePart(action) {
  const part = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${argsString(action)}`;
  return action.required ? part : `[${part}]`;
}

/** `-h, --help` / `--a A`: how an option appears in the options list. */
function formatInvocation(action) {
  if (action.nargs === 0) {
    return action.optionStrings.join(', ');
  }
  const args = argsString(action);
  return action.optionStrings.map((opt) => `${opt} ${args}`).join(', ');
}

/** The `usage: ...` line, without a trailing newline. */
export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart);
  return `usage: ${[prog, ...parts].join(' ')}`;
}

/** The full `--help` output, terminated by exactly one newline. */
export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);

  // The help column sits two spaces past the widest invocation, but never
  // further out than MAX_HELP_POSITION.
  const maxLength = Math.max(...invocations.map((s) => s.length)) + INDENT;
  const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - INDENT - 2;

  const pad = ' '.repeat(INDENT);
  const lines = actions.map((action, i) => {
    const invocation = invocations[i];
    if (!action.help) {
      return pad + invocation;
    }
    if (invocation.length <= actionWidth) {
      return pad + invocation.padEnd(actionWidth) + '  ' + action.help;
    }
    // Too wide to share a line: the help text drops to the next row.
    return pad + invocation + '\n' + ' '.repeat(helpPosition) + action.help;
  });

  return [formatUsage(prog, actions), '', 'options:', ...lines].join('\n') + '\n';
}

