/**
 * A faithful, dependency-free reimplementation of the argument parser the
 * original program builds:
 *
 *     parser = ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *
 * The point of reproducing the parser rather than hand-rolling an ad-hoc
 * `process.argv` scan is that the reference has a number of behaviours that a
 * naive scan gets wrong: `--a=value`, prefix abbreviation of `--help`,
 * `--`-terminated option lists, and the rule that lets a value like `-5`
 * through while rejecting `-x`.
 */

import { writeSync } from 'node:fs';
import { basename } from 'node:path';

import { ArgumentError, ParserExit, UsageError } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

const PREFIX_CHARS = '-';

/**
 * Values that look like negative numbers are treated as values, not options.
 *
 * `\p{Nd}` stands in for Python's `\d`, which matches any Unicode decimal
 * digit, so `-٥` is a number just as `-5` is. The `\n?$` tail reproduces
 * Python's `$`, which also matches immediately before a single trailing
 * newline — so a value of `"-5\n"` is accepted where `"-5\n6"` is not.
 */
const NEGATIVE_NUMBER = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

/** Split on the first `=` only; `--a=x=y` carries the value `x=y`. */
function splitOnFirstEquals(text) {
  const at = text.indexOf('=');
  return [text.slice(0, at), text.slice(at + 1)];
}

/** How an action is named in error messages: `-h/--help`, `--a`. */
function actionName(action) {
  return action.optionStrings.join('/');
}

/** Python's `repr()` for the strings that appear in error messages. */
function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of text) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (ch < ' ' || ch === '\x7f') {
      out += '\\x' + ch.codePointAt(0).toString(16).padStart(2, '0');
    } else out += ch;
  }
  return quote + out + quote;
}

/**
 * The parser for this program: `-h/--help` plus a required `--a A`.
 *
 * `parse` returns `{ a }` on success. Anything that would make the reference
 * print usage or help and stop is signalled by throwing, so that the I/O and
 * the exit code stay in one place ({@link runParse}).
 */
export class Parser {
  constructor(prog) {
    this.prog = prog;

    this.actions = [
      {
        kind: 'help',
        optionStrings: ['-h', '--help'],
        dest: 'help',
        nargs: 0,
        required: false,
        help: 'show this help message and exit',
      },
      {
        kind: 'store',
        optionStrings: ['--a'],
        dest: 'a',
        metavar: 'A',
        nargs: 1,
        required: true,
        help: null,
      },
    ];

    // Insertion order matters: it decides the order option strings are listed
    // in an "ambiguous option" message.
    this.optionStringActions = new Map();
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        this.optionStringActions.set(optionString, action);
      }
    }

    // No declared option looks like a negative number, so negative numbers
    // are unambiguously values here.
    this.hasNegativeNumberOptionals = [...this.optionStringActions.keys()]
      .some((optionString) => NEGATIVE_NUMBER.test(optionString));
  }

  usage() {
    return formatUsage(this.prog, this.actions);
  }

  help() {
    return formatHelp(this.prog, this.actions);
  }

  /**
   * Classify one command-line token.
   *
   * Returns `null` when the token is a value, or a
   * `[action, optionString, sep, explicitArg]` tuple when it is an option.
   * `action` is `null` in that tuple for a token that looks like an option but
   * matches nothing declared.
   */
  parseOptional(argString) {
    // An empty string is always a value.
    if (argString === '') return null;

    // So is anything that does not start with a prefix character.
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    // An exact match wins outright.
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null, null];
    }

    // A lone `-` is a value.
    if (argString.length === 1) return null;

    // `--a=value`: an exact match on the part before the `=`.
    if (argString.includes('=')) {
      const [optionString, explicitArg] = splitOnFirstEquals(argString);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, '=', explicitArg];
      }
    }

    // Otherwise fall back to abbreviations and glued-on short-option values.
    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map(([, optionString]) => optionString).join(', ');
      throw new UsageError(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    // It starts with `-`, but it may still be a negative number...
    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;

    // ...or a value that happens to contain a space.
    if (argString.includes(' ')) return null;

    // An option, but not one we know.
    return [null, argString, null, null];
  }

  /** Candidate interpretations of a token that was not an exact match. */
  getOptionTuples(argString) {
    const result = [];
    const isPrefix = (ch) => ch !== undefined && PREFIX_CHARS.includes(ch);

    if (isPrefix(argString[0]) && isPrefix(argString[1])) {
      // Long option: match on any unambiguous prefix, e.g. `--hel` -> `--help`.
      let optionPrefix = argString;
      let explicitArg = null;
      let sep = null;
      if (argString.includes('=')) {
        [optionPrefix, explicitArg] = splitOnFirstEquals(argString);
        sep = '=';
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([action, optionString, sep, explicitArg]);
        }
      }
    } else if (isPrefix(argString[0]) && !isPrefix(argString[1])) {
      // Short option, whose value may be concatenated onto it: `-hx`.
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push([action, optionString, '', shortExplicitArg]);
        } else if (optionString.startsWith(argString)) {
          result.push([action, optionString, null, null]);
        }
      }
    }
    return result;
  }

  /**
   * How many of the following tokens this option consumes.
   *
   * The reference matches a regex over a string of per-token classification
   * characters: `A` for a value, `O` for an option, `-` for the `--`
   * separator. For an option the `-` alternatives are stripped out of the
   * pattern, which is why `--a -- x` fails rather than skipping over the `--`.
   */
  matchArgument(action, patternString) {
    const nargsPattern = action.nargs === 0 ? '()' : '(A)';
    const match = new RegExp('^' + nargsPattern).exec(patternString);
    if (match === null) {
      throw new ArgumentError(actionName(action), 'expected one argument');
    }
    return match[1].length;
  }

  parse(argStrings) {
    // Classify every token up front. Everything after the first `--` is a
    // value, and the `--` itself gets its own classification.
    const patterns = [];
    const optionTuples = new Map();
    let seenDoubleDash = false;
    for (let i = 0; i < argStrings.length; i++) {
      if (!seenDoubleDash && argStrings[i] === '--') {
        seenDoubleDash = true;
        patterns.push('-');
      } else if (seenDoubleDash) {
        patterns.push('A');
      } else {
        const tuple = this.parseOptional(argStrings[i]);
        if (tuple === null) {
          patterns.push('A');
        } else {
          optionTuples.set(i, tuple);
          patterns.push('O');
        }
      }
    }

    const namespace = {};
    const seen = new Set();
    const extras = [];

    const takeAction = (action, args) => {
      seen.add(action);
      if (action.kind === 'help') throw new ParserExit(0, this.help());
      namespace[action.dest] = args[0];
    };

    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionTuples.get(startIndex);
      const actionTuples = [];
      let stop;

      for (;;) {
        // Looked like an option, but matched nothing declared.
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this.matchArgument(action, 'A');

          if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
            // A single-dash option that takes no value, with a tail glued on:
            // the tail may itself be more short options, as in `-hx`. An
            // explicit `=` rules that reading out.
            if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
              throw new ArgumentError(
                actionName(action),
                `ignored explicit argument ${pyRepr(explicitArg)}`,
              );
            }
            actionTuples.push([action, []]);
            optionString = optionString[0] + explicitArg[0];
            const next = this.optionStringActions.get(optionString);
            if (next === undefined) {
              extras.push(optionString[0] + explicitArg);
              stop = startIndex + 1;
              break;
            }
            action = next;
            explicitArg = explicitArg.slice(1);
            if (explicitArg === '') {
              sep = null;
              explicitArg = null;
            } else if (explicitArg[0] === '=') {
              sep = '=';
              explicitArg = explicitArg.slice(1);
            } else {
              sep = '';
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg]]);
            break;
          } else {
            throw new ArgumentError(
              actionName(action),
              `ignored explicit argument ${pyRepr(explicitArg)}`,
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = this.matchArgument(action, patterns.slice(start).join(''));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop)]);
          break;
        }
      }

      for (const [act, args] of actionTuples) takeAction(act, args);
