import { writeSync } from 'node:fs';
import { basename } from 'node:path';

import { ArgumentError, ParserExit, UsageError } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

const PREFIX_CHARS = '-';

