    this.actions = [
      {
        kind: 'help',
        optionStrings: ['-h', '--help'],
        dest: 'help',
        nargs: 0,
        required: false,
        help: 'show this help message and exit',
      },
      {
        kind: 'store',
        optionStrings: ['--a'],
        dest: 'a',
        metavar: 'A',
        nargs: 1,
        required: true,
        help: null,
      },
    ];

    // Insertion order matters: it decides the order option strings are listed
    // in an "ambiguous option" message.
    this.optionStringActions = new Map();
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        this.optionStringActions.set(optionString, action);
      }
    }

    // No declared option looks like a negative number, so negative numbers
    // are unambiguously values here.
    this.hasNegativeNumberOptionals = [...this.optionStringActions.keys()]
      .some((optionString) => NEGATIVE_NUMBER.test(optionString));
  }

  usage() {
    return formatUsage(this.prog, this.actions);
  }

  help() {
    return formatHelp(this.prog, this.actions);
  }

